import React from "react";
import tw from "twin.macro";

const StepsSection = tw.section`w-full flex flex-col items-center py-12 bg-gray-500`;
const StepsTitle = tw.h2`text-2xl font-bold mb-6 text-primary-700`;
const StepsList = tw.ol`list-decimal pl-6 max-w-xl text-lg text-gray-800`;
const Step = tw.li`mb-4`;

export default function RegistrationSteps() {
  return (
    <StepsSection>
      <StepsTitle>How to Register for BGM Referral</StepsTitle>
      <StepsList>
        <Step>Click the <b>Register to Get Referral Link</b> button above.</Step>
        <Step>Fill in your name and email on the registration page.</Step>
        <Step>If you have a referral link, it will be auto-filled. Otherwise, you can register directly.</Step>
        <Step>After registration, check your email for confirmation and your unique referral link.</Step>
        <Step>Enter your Ticket ID to join the referral programme and unlock sharing options.</Step>
        <Step>Share your referral link with friends and track your referrals on the leaderboard!</Step>
      </StepsList>
    </StepsSection>
  );
}
